const DEV="DevOps, Cloud & Delivery";

addTopic({id:"dev01",cat:DEV,t:"DevOps lifecycle and culture",d:"Understand",p:"P0",n:"Refresh",h:1.5,
what:"DevOps is a way of working where development and operations share responsibility for building, releasing and running software, supported by automation. The lifecycle is usually drawn as a loop: plan, code, build, test, release, deploy, operate, monitor, and back to plan.",
why:"Most delivery delays sit in hand-offs between teams. A TPM who understands DevOps can spot those bottlenecks and push for automation and shared ownership instead of more meetings.",
concepts:["The DevOps loop","Shared ownership: you build it, you run it","Automation over manual hand-offs","Small, frequent changes","Feedback from production","DORA metrics: deployment frequency, lead time, change failure rate, time to restore"],
learn:["atlDevops"],
doIt:"Map how a change in your current project moves from idea to production. Mark each manual hand-off and how long it waits.",
prove:"Propose three improvements to that flow, each with the delay it would remove.",
interview:"What does DevOps mean to you, and how have you applied it as a programme manager?",
covers:["DevOps Fundamentals"]},
{sections:[
 {h:"The loop",flow:[["Dev",[["Plan","backlog"],["Code","branches"],["Build","artifacts"],["Test","automated"]]],["Ops",[["Release","approve"],["Deploy","to servers"],["Operate","run"],["Monitor","feedback"]]]],flowLabel:"DevOps lifecycle",p:["Atlassian describes DevOps as practices that automate and integrate the work of development and IT teams so they can build, test and release software faster and more reliably."]},
 {h:"Culture before tools",bullets:["Shared goals: developers care about uptime, operations care about delivery speed.","Blameless learning from incidents.","Small batches: smaller changes are easier to test, review and roll back.","Everything as code: infrastructure, config and pipelines are versioned."]},
 {h:"The four DORA metrics",table:[["Metric","What it shows","Good direction"],["Deployment frequency","How often you release","Up"],["Lead time for changes","Commit to production time","Down"],["Change failure rate","Share of releases causing problems","Down"],["Time to restore service","How fast you recover","Down"]],p:["These four, from the DevOps Research and Assessment programme, balance speed and stability. Reporting them shows whether process changes actually help."]},
 {h:"Where a TPM helps",bullets:["Make waiting time visible: approvals, environment queues, manual testing.","Fund automation work in the roadmap instead of treating it as overhead.","Agree release and incident processes across teams."]},
 {h:"Key terms",gloss:[["DevOps","Shared development and operations practices with automation"],["Lead time","Time from code commit to production"],["Change failure rate","Share of deployments that cause failures"],["Hand-off","Work passing between teams, often with waiting"],["Toil","Repetitive manual operational work"]]}
],
quiz:[["Name the four DORA metrics.","Deployment frequency, lead time for changes, change failure rate, time to restore service."],["Why do small changes help?","They are easier to test, review and roll back."],["Is DevOps a tool?","No; it is a way of working supported by tools."],["What does 'everything as code' mean?","Infrastructure, configuration and pipelines are stored and reviewed in version control."]],
deeper:["atlDevops","atlCicd"]},
{prac:["Add DORA metrics to the monthly engineering review; they start useful conversations about where time goes.","When a release slips, ask where the change waited, not who was slow."],
 mis:[["DevOps is a job title.","It is a shared way of working; a 'DevOps team' alone can become another silo."],["Speed reduces stability.","High performers usually improve both through automation and small changes."],["Buying tools makes us DevOps.","Culture and process changes matter more."]]});

addTopic({id:"dev02",cat:DEV,t:"Git concepts: repos, branches, commits, merge, rebase, tags",d:"Use",p:"P0",n:"New",h:2.5,
what:"Git is a version control system: it records every change to files as commits, lets people work in parallel on branches, and combines work through merge or rebase. GitHub, GitLab and Bitbucket host Git repositories online and add reviews and automation.",
why:"Every engineering conversation about releases, hotfixes and conflicts uses Git words. Knowing them lets you follow, question and plan without needing to code.",
concepts:["Repository, commit, history","Branch and main branch","Merge vs rebase","Merge conflicts","Cherry-pick for hotfixes","Tags for releases","Hosting platforms"],
learn:["proGit","gitBranch","ghHello"],
doIt:"Complete GitHub's Hello World guide: create a repository, a branch, a commit and a pull request, then merge it.",
prove:"Explain in five sentences, using your own repo, how a hotfix would reach production while a feature branch is still in progress.",
interview:"Two developers changed the same file and there's a merge conflict. What does that mean and how is it resolved?",
covers:["Version Control (Git)","Git, GitHub, GitLab, Bitbucket","Repository, Branch, Commit","Merge, Rebase, Cherry-pick","Conflict Resolution, Tags"]},
{sections:[
 {h:"The core words",table:[["Term","Plain meaning"],["Repository","A project folder with its full change history"],["Commit","A saved snapshot with a message and author"],["Branch","A separate line of work"],["Main","The shared, stable branch"],["Merge","Combine one branch's work into another"],["Rebase","Replay commits on top of another branch to keep a straight history"],["Cherry-pick","Copy one specific commit to another branch"],["Tag","A named marker for a commit, often a release like v2.3.0"]]},
 {h:"How branches flow",steps:["Create a branch from main for a feature.","Make commits on it.","Open a pull request for review.","Merge into main when approved and tests pass.","Tag the release commit when it ships."],p:["The Pro Git book notes Git branching is lightweight, so creating and switching branches is nearly instant; that is why teams branch for every small change."]},
 {h:"Merge conflicts",p:["A conflict happens when two branches changed the same lines differently. Git can't choose, so a person decides which version (or combination) to keep. Conflicts are normal; long-lived branches make them bigger and riskier."]},
 {h:"Hotfixes and cherry-pick",p:["If production needs an urgent fix while main contains unfinished work, the team can branch from the release tag, fix it there, release, then bring the same fix back to main, sometimes by cherry-picking the commit."]},
 {h:"Key terms",gloss:[["Commit","A recorded change in Git"],["Branch","An independent line of development"],["Merge conflict","Overlapping changes Git can't combine automatically"],["Rebase","Moving commits onto a new base"],["Tag","A label marking a specific commit"]]}
],
quiz:[["What is a commit?","A saved snapshot of changes with a message and author."],["When does a merge conflict happen?","When two branches change the same lines differently."],["What is cherry-pick used for?","Copying a specific commit, such as a hotfix, to another branch."],["Why tag releases?","To mark exactly which commit was shipped."]],
deeper:["proGit","gitBranch","ghHello"]},
{prac:["Ask for release tags in release notes; it makes 'what exactly is in production?' answerable in seconds.","Encourage short-lived branches; long ones are the main source of painful conflicts."],
 mis:[["Git and GitHub are the same.","Git is the tool; GitHub hosts repositories and adds collaboration."],["Conflicts mean someone made a mistake.","They are a normal part of parallel work."],["Rebase is always better than merge.","Each has trade-offs; teams pick a convention."]]});

addTopic({id:"dev03",cat:DEV,t:"Pull requests and branching strategies",d:"Understand",p:"P0",n:"New",h:1.5,
what:"A pull request (GitHub) or merge request (GitLab) proposes merging a branch, so others can review the change and automated checks can run. A branching strategy is the team's agreed pattern for branches, such as GitHub flow, trunk-based development or Git flow.",
why:"Pull requests are where quality, knowledge sharing and release readiness meet. The branching strategy shapes how fast and safely a team can ship.",
concepts:["Pull request and merge request","Reviews, approvals and status checks","Branch protection rules","GitHub flow","Trunk-based development and feature flags","Git flow with release branches"],
learn:["ghFlow","googleCr"],
doIt:"Open a recent pull request in any public repo and note: the description, linked issue, checks that ran, review comments and how long it took to merge.",
prove:"Write a one-page PR guideline for a team: size limits, description template, required checks and review time targets.",
interview:"Pull requests in our team wait days for review. What would you do?",
covers:["Pull Request, Merge Request","Branching Strategies"]},
{sections:[
 {h:"Anatomy of a good pull request",bullets:["A clear title and summary of what changed and why.","A link to the ticket or issue.","Screenshots or test evidence where useful.","Small enough to review in under an hour.","Passing automated checks."],p:["GitHub's guide to GitHub flow recommends summarising the change and the problem it solves, and linking related issues so stakeholders can follow."]},
 {h:"Common branching strategies",table:[["Strategy","How it works","Fits"],["GitHub flow","Short feature branches off main, merged via PR, main always deployable","Web apps with frequent releases"],["Trunk-based","Very short branches or direct commits to main, unfinished work hidden behind feature flags","High-frequency continuous delivery"],["Git flow","Long-lived develop and release branches, hotfix branches","Versioned products with scheduled releases, such as mobile apps"]]},
 {h:"Guardrails",bullets:["Branch protection: no direct pushes to main.","Required reviews: at least one approval, or code owners for sensitive areas.","Required status checks: tests, lint and security scans must pass.","Merge methods: squash, merge commit or rebase, chosen by convention."]},
 {h:"Review speed is a delivery lever",p:["Waiting for review is often the largest share of lead time. Teams improve it with smaller PRs, review time targets, rotating reviewers and making review part of daily work rather than an extra."]},
 {h:"Key terms",gloss:[["Pull request","A proposal to merge changes, with review"],["Status check","An automated test result shown on a PR"],["Branch protection","Rules preventing unsafe changes to key branches"],["Feature flag","A switch to turn features on or off without deploying"],["Code owner","A person or team required to review certain files"]]}
],
quiz:[["What is the difference between a PR and an MR?","Same idea; GitHub calls it pull request, GitLab merge request."],["Which strategy suits scheduled mobile releases?","Git flow or a release-branch approach."],["What hides unfinished work in trunk-based development?","Feature flags."],["Give one way to speed up reviews.","Smaller PRs, review time targets, rotating reviewers (any one)."]],
deeper:["ghFlow","googleCr"]},
{prac:["Track 'time to first review' as a team metric; it often reveals more delay than coding time.","Agree a PR template with the team so reviewers see context, not just code."],
 mis:[["Reviews are just bug hunting.","They also spread knowledge and keep design consistent."],["Bigger PRs save time.","They take longer to review and hide more defects."],["One branching strategy is best for everyone.","It depends on release cadence and product type."]]});

addTopic({id:"dev04",cat:DEV,t:"CI vs continuous delivery vs continuous deployment",d:"Understand",p:"P0",n:"New",h:2,
what:"Continuous integration (CI) means developers merge small changes often and every change is automatically built and tested. Continuous delivery means every change that passes is automatically prepared and can be released at any time with a button press. Continuous deployment goes one step further: every passing change goes to production automatically.",
why:"People use 'CI/CD' loosely. Knowing the difference lets you set realistic release plans and know which approvals and tests are needed.",
concepts:["Integrating often to avoid big-bang merges","Automated build and test on every change","Always-releasable main branch","Manual approval vs automatic release","Prerequisites: test coverage, monitoring, rollback","Choosing the right level for your product"],
learn:["atlCicd"],
doIt:"For your current product, decide which of the three you have today, and list what's missing to reach the next level.",
prove:"Write a short roadmap with milestones from today's process to continuous delivery.",
interview:"Should we move to continuous deployment? What would need to be true first?",
covers:["CI/CD Basics","Continuous Integration","Continuous Delivery","Continuous Deployment"]},
{sections:[
 {h:"Three levels",table:[["Practice","What's automated","Release to production"],["Continuous integration","Build and tests on every merge","Separate, often manual"],["Continuous delivery","Build, test and deploy to staging; release-ready package","Human presses the button"],["Continuous deployment","Everything, including production release","Automatic when checks pass"]],p:["Atlassian sums it up: continuous integration is part of both, and continuous deployment is like continuous delivery except releases happen automatically."]},
 {h:"What each requires",bullets:["CI: a shared repo, automated build, fast reliable tests, a culture of merging daily.","Continuous delivery: automated deployment to environments, good test coverage, release checklists turned into automation.","Continuous deployment: strong automated tests, feature flags, monitoring with alerts, fast rollback."]},
 {h:"Choosing the level",p:["Web services often aim for continuous deployment. Mobile apps can't deploy continuously to users because app stores review each release, so they usually do continuous delivery to internal testers. Regulated products may keep a human approval step for compliance."]},
 {h:"Signs CI isn't really happening",bullets:["Branches live for weeks.","The build is often red and nobody fixes it quickly.","Tests are skipped to get releases out.","Integration happens in a big merge before release."]},
 {h:"Key terms",gloss:[["CI","Automatically building and testing every change"],["Continuous delivery","Always having a releasable build, released by a person"],["Continuous deployment","Automatically releasing every passing change"],["Pipeline","The automated sequence of build, test and deploy steps"],["Green build","A build where all checks passed"]]}
],
quiz:[["What is the difference between continuous delivery and deployment?","Delivery needs a human to release; deployment releases automatically."],["Why can't most mobile apps do continuous deployment to users?","App store review sits between build and users."],["Name two prerequisites for continuous deployment.","Strong automated tests, feature flags, monitoring, fast rollback (any two)."],["Give a sign that CI isn't really happening.","Long-lived branches or a build that stays red."]],
deeper:["atlCicd","testPyramid"]},
{prac:["Treat a broken main build as a stop-the-line event; a red build that lingers erodes trust in the whole pipeline.","Use the three levels as a maturity roadmap in quarterly planning."],
 mis:[["CI/CD is a tool.","It's a practice that tools support."],["Continuous deployment means no testing.","It needs more automated testing, not less."],["Everyone should do continuous deployment.","The right level depends on product, risk and regulation."]]});

addTopic({id:"dev05",cat:DEV,t:"Build and release pipelines and artifacts",d:"Understand",p:"P0",n:"New",h:1.5,
what:"A build pipeline turns source code into a tested, versioned artifact (a package, container image or app file). A release pipeline takes that same artifact and promotes it through environments such as dev, staging and production. Build once, deploy many times.",
why:"Release problems often come from building different things for different environments. Understanding artifacts and promotion helps you ask the right questions in release reviews.",
concepts:["Build vs deploy vs release","Artifacts and versioning","Artifact repositories and registries","Environments: dev, QA, staging, production","Promotion of the same artifact","Release approvals and gates"],
learn:["atlCicd","twelveConfig"],
doIt:"List your product's environments and how a change moves through them. Note whether the same artifact is promoted or rebuilt each time.",
prove:"Draw the build and release pipeline for your product, with gates and who approves each.",
interview:"What's the difference between deploying and releasing?",
covers:["Build Pipeline, Release Pipeline","Build Artifacts","Build, Deploy, Release","Production (promotion)"]},
{sections:[
 {h:"Build, deploy, release",table:[["Step","Meaning"],["Build","Turn code into a runnable artifact and test it"],["Deploy","Put the artifact onto servers in an environment"],["Release","Make the change available to users, possibly via a feature flag"]],p:["Separating deploy from release is powerful: code can be deployed dark and switched on later for a few users, then everyone."]},
 {h:"Build once, promote many",flow:[["Build",[["Compile and test","CI"],["Artifact v2.3.0","stored in registry"]]],["Promote",[["Dev","auto"],["Staging","auto + tests"],["Production","approval"]]]],flowLabel:"Artifact promotion",p:["The Twelve-Factor App separates build, release and run stages, and keeps configuration in the environment, so the same build can run anywhere with different settings."]},
 {h:"Artifacts",bullets:["Examples: a Docker image, a .jar file, an npm package, an Android AAB, an iOS IPA.","Each has a version number and is stored in a repository or registry.","Artifacts are never changed after build; a fix means a new version."]},
 {h:"Gates and approvals",bullets:["Automated gates: tests, security scans, performance checks.","Manual gates: product sign-off, change advisory approval for regulated systems.","Keep manual gates few and fast; every one adds lead time."]},
 {h:"Key terms",gloss:[["Artifact","The packaged output of a build"],["Registry","A store for artifacts such as container images"],["Promotion","Moving the same artifact to the next environment"],["Environment","A separate setup such as staging or production"],["Gate","A check that must pass before promotion"]]}
],
quiz:[["What is the difference between deploy and release?","Deploy puts code on servers; release makes it available to users."],["Why build once and promote?","So what was tested is exactly what reaches production."],["Give two examples of artifacts.","Docker image, jar file, npm package, AAB, IPA (any two)."],["Where does environment-specific config live?","In the environment, not in the artifact."]],
deeper:["atlCicd","twelveConfig"]},
{prac:["In release reviews ask 'which artifact version is going out and where was it tested?'. It surfaces rebuild risks quickly.","Count manual gates in your pipeline; each is a candidate for automation."],
 mis:[["Rebuilding for production is fine.","A rebuild may differ from what was tested."],["Deployment means users see it.","With feature flags, deployed code can stay hidden."],["More approval gates mean more safety.","Too many slow delivery without improving quality."]]});

addTopic({id:"dev06",cat:DEV,t:"GitHub Actions hands-on (plus Jenkins and GitLab CI overview)",d:"Build",p:"P0",n:"New",h:3,
what:"GitHub Actions is a CI/CD platform built into GitHub. You describe workflows in YAML files in your repository; they run on triggers such as a push or pull request. Jenkins and GitLab CI do the same job: Jenkins is self-hosted and plugin-based, GitLab CI is built into GitLab.",
why:"Reading and tweaking a pipeline file is a practical skill. You've already seen GitHub Actions run tests for this learning hub's repo; now you can understand and change one.",
concepts:["Workflow, trigger, job, step","Runners: hosted vs self-hosted","Secrets in pipelines","Status checks on pull requests","Jenkinsfile and plugins","GitLab .gitlab-ci.yml stages and jobs"],
learn:["ghActionsQs","jenkinsPipe","gitlabCi"],
doIt:"Follow the GitHub Actions quickstart in a test repo, then ask Claude to add a job that runs a simple test on every pull request.",
prove:"Open the CI workflow in this learning hub's repository and explain, step by step, what each job does.",
interview:"Walk me through a CI pipeline you've worked with. What runs and when?",
covers:["GitHub Actions, GitLab CI","Jenkins","CI/CD Pipeline Setup (Level 3)"]},
{sections:[
 {h:"The building blocks",table:[["Term","Meaning"],["Workflow","A YAML file in .github/workflows describing automation"],["Trigger (on)","When it runs: push, pull_request, schedule, manual"],["Job","A group of steps that runs on one machine"],["Step","A single command or reusable action"],["Runner","The machine that runs the job"]],p:["GitHub's docs describe Actions as a CI/CD platform to automate build, test and deployment pipelines, with workflow files stored in the .github/workflows directory."]},
 {h:"Reading a simple workflow",steps:["name: a label shown in the Actions tab.","on: pull_request means it runs for every PR.","jobs: test runs on ubuntu-latest.","steps: check out the code, install dependencies, run the tests.","If any step fails, the check turns red on the pull request."]},
 {h:"Jenkins and GitLab CI",table:[["Tool","Where config lives","Notes"],["GitHub Actions","Workflow YAML in the repo","Hosted runners, large marketplace of actions"],["GitLab CI","A .gitlab-ci.yml file at the repo root","Stages and jobs; runners execute jobs"],["Jenkins","A Jenkinsfile in the repo","Self-hosted, highly extensible via plugins"]]},
 {h:"Safe pipelines",bullets:["Store keys as encrypted secrets, never in the YAML.","Limit permissions of the pipeline token.","Pin third-party actions to versions you trust.","Keep pipelines fast; slow CI tempts people to skip it."]},
 {h:"Key terms",gloss:[["Workflow","An automated process defined in YAML"],["Runner","A machine that executes pipeline jobs"],["Action","A reusable step in GitHub Actions"],["Jenkinsfile","Pipeline definition for Jenkins"],["YAML","A human-readable configuration format"]]}
],
quiz:[["Where do GitHub Actions workflows live?","In the .github/workflows folder."],["What does 'on: pull_request' do?","Runs the workflow for each pull request."],["Which tool is self-hosted and plugin-based?","Jenkins."],["Where should API keys for pipelines go?","Encrypted secrets, not the YAML file."]],
deeper:["ghActionsQs","gitlabCi","jenkinsPipe"]},
{prac:["Ask for pipeline duration on the team dashboard; anything over 15 minutes slows every PR.","When a pipeline fails, read the failing step's log first; most failures name the problem clearly."],
 mis:[["CI config is only for DevOps engineers.","Anyone can read YAML and follow what runs."],["Hosted runners are always enough.","Some builds need self-hosted runners for hardware or network access."],["Secrets in private repos are safe.","Use the platform's secret store."]]});

addTopic({id:"dev07",cat:DEV,t:"Testing in the pipeline",d:"Understand",p:"P1",n:"Refresh",h:1,
what:"Automated tests run in the pipeline so every change is checked before it moves on. The usual mix follows the test pyramid: many fast unit tests, fewer integration tests, and a small number of slow end-to-end tests.",
why:"Test strategy decides how confidently and quickly a team can release. A TPM should know what is tested where, how long it takes and what flaky tests cost.",
concepts:["Test pyramid","Unit, integration, end-to-end tests","Where each runs: PR, merge, nightly, pre-release","Flaky tests","Coverage as a signal, not a target","Smoke tests after deployment"],
learn:["testPyramid"],
doIt:"List the automated tests in your product's pipeline, where each runs and how long it takes.",
prove:"Write a one-page test strategy: what runs on PR, on merge, nightly and after deploy.",
interview:"How would you balance test coverage and release speed?",
covers:["Automated Testing"]},
{sections:[
 {h:"The pyramid",table:[["Layer","Checks","Speed","Quantity"],["Unit","One function or class","Milliseconds","Many"],["Integration","Components working together, such as API and database","Seconds","Some"],["End-to-end","A full user journey through the UI","Minutes","Few"]],p:["Martin Fowler's practical test pyramid explains why: higher-level tests are slower and more brittle, so most checks should sit lower down."]},
 {h:"Where tests run",table:[["Stage","Tests"],["Pull request","Unit, lint, fast integration"],["Merge to main","Full integration, security scans"],["Nightly","Long end-to-end and performance suites"],["After deploy","Smoke tests on the live environment"]]},
 {h:"Flaky tests",p:["A flaky test sometimes passes and sometimes fails with no code change. They waste time and teach people to ignore red builds. Track them, quarantine them, and fix or delete them quickly."]},
 {h:"Coverage",bullets:["Coverage shows which lines tests execute, not whether behaviour is right.","Useful for spotting untested risky areas.","Harmful as a hard target; teams write shallow tests to hit the number."]},
 {h:"Key terms",gloss:[["Unit test","Tests a small piece of code in isolation"],["Integration test","Tests parts working together"],["End-to-end test","Tests a complete user flow"],["Flaky test","A test with inconsistent results"],["Smoke test","A quick check that the basics work after deploy"]]}
],
quiz:[["Why have more unit tests than end-to-end tests?","They are faster and less brittle."],["What is a flaky test?","One that passes or fails without code changes."],["What do smoke tests check?","That the basics work right after deployment."],["Is high coverage proof of quality?","No; it shows code was run, not that behaviour is correct."]],
deeper:["testPyramid"]},
{prac:["Report flaky test count in sprint reviews; it's a hidden tax on every developer.","Make sure release sign-off includes post-deploy smoke tests, not only pre-release tests."],
 mis:[["More end-to-end tests mean more safety.","They're slow and brittle; balance the pyramid."],["100% coverage means no bugs.","Coverage measures execution, not correctness."],["QA tests at the end.","Testing runs throughout the pipeline."]]});

addTopic({id:"dev08",cat:DEV,t:"Servers, VMs, Linux and scripting basics",d:"Understand",p:"P1",n:"New",h:1.5,
what:"A server is a computer that provides a service over a network. It can be bare metal (a physical machine), a virtual machine (a software-defined computer sharing physical hardware) or a container. Most servers run Linux and are managed through a command-line shell such as Bash, often over SSH; Windows servers use PowerShell.",
why:"Incident calls and infrastructure plans use these words constantly. Knowing them helps you understand what's being changed and what could break.",
concepts:["Bare metal vs VM vs container","Linux vs Windows Server","Shell, terminal, Bash, PowerShell","SSH for remote access","Basic commands and scripts","Why servers are treated as replaceable"],
learn:["ubuntuCli","mdnCli"],
doIt:"Work through the first sections of the Ubuntu command-line tutorial (navigate folders, create files, list contents). On Windows you can use WSL.",
prove:"Explain to a non-technical colleague what happens when an engineer 'SSHes into a box to check the logs'.",
interview:"What's the difference between a VM and a container?",
covers:["Linux, Windows Server","Server, VM, Bare Metal","SSH, Shell, Bash, PowerShell"]},
{sections:[
 {h:"Kinds of servers",table:[["Type","What it is","Trade-off"],["Bare metal","A dedicated physical machine","Full performance, slow to provision"],["Virtual machine","A software computer with its own OS on shared hardware","Flexible, minutes to create"],["Container","An isolated process sharing the host's OS kernel","Very light and fast, less isolation"]]},
 {h:"The command line",p:["Ubuntu's tutorial describes the command line as a text interface to the computer, also called the shell, terminal or console. Engineers use it because it is precise, scriptable and works the same on remote servers."],table:[["Command","Does"],["pwd","Shows the current folder"],["ls","Lists files"],["cd","Changes folder"],["cat / less","Shows a file"],["tail -f","Follows a log file live"],["sudo","Runs a command as administrator"]]},
 {h:"SSH",p:["SSH (Secure Shell) opens an encrypted terminal on a remote server. Access is usually by key pairs rather than passwords. In mature setups, direct SSH into production is rare and audited; changes go through pipelines instead."]},
 {h:"Pets vs cattle",p:["Old practice treated servers like pets: named, hand-configured and nursed when sick. Modern practice treats them like cattle: identical, created from code, and replaced rather than repaired. This makes scaling and recovery predictable."]},
 {h:"Key terms",gloss:[["Server","A computer providing a service over a network"],["Virtual machine","A software-emulated computer"],["Shell","A program that runs typed commands"],["SSH","Secure remote terminal access"],["Script","A file of commands run together"]]}
],
quiz:[["What is the difference between a VM and a container?","A VM has its own OS; a container shares the host OS kernel."],["What is SSH?","Encrypted remote terminal access to a server."],["What does 'tail -f' do?","Follows a log file as it updates."],["Why treat servers as cattle?","Replaceable servers built from code make scaling and recovery predictable."]],
deeper:["ubuntuCli","mdnCli"]},
{prac:["Ask how often engineers SSH into production; frequent manual access is a reliability and audit risk.","Learn five commands; it makes incident calls much easier to follow."],
 mis:[["The cloud means no servers.","Servers still exist; the provider manages the hardware."],["Command line is only for experts.","Basic commands are learnable in an hour."],["VMs and containers are the same.","They isolate at different levels."]]});

addTopic({id:"dev09",cat:DEV,t:"Containers and Docker",d:"Understand",p:"P0",n:"New",h:2,
what:"A container packages an application with everything it needs (code, runtime, libraries, settings) so it runs the same anywhere. Docker builds images from a Dockerfile, runs them as containers and stores them in registries such as Docker Hub.",
why:"Containers are the standard way to ship modern software, including this learning hub. Understanding them explains 'works on my machine' problems and how deployments happen.",
concepts:["Image vs container","Dockerfile","Layers and caching","Registries and tags","Docker Compose for multi-container apps","Volumes for persistent data"],
learn:["dockerOverview"],
doIt:"Open this project's docker-compose.yml and identify each service, its image or build folder, and its ports.",
prove:"Explain to a teammate how docker compose up starts the database, backend and frontend for the learning hub.",
interview:"Why do teams use containers, and what problems do they solve?",
covers:["Containerization (Docker)","Docker, Containers, Images","Container Registry"]},
{sections:[
 {h:"Image and container",table:[["Term","Analogy","Meaning"],["Image","A recipe or template","Read-only package built from a Dockerfile"],["Container","A dish made from the recipe","A running instance of an image"],["Registry","A recipe library","A store of images, like Docker Hub"],["Tag","An edition label","A version of an image, like app:2.3.0"]],p:["Docker's overview describes an image as a read-only template with instructions for creating a container, and a container as a runnable instance of an image."]},
 {h:"Why containers help",bullets:["Same environment from laptop to production: fewer 'works on my machine' bugs.","Fast start-up, so scaling up is quick.","Isolation: apps don't conflict over library versions.","Clear artifacts: the image is the thing that's tested and deployed."]},
 {h:"Compose for local stacks",p:["Docker Compose starts several containers together from one file. This project's docker-compose.yml runs three services: a PostgreSQL database, the FastAPI backend and the Next.js frontend, wired together on a private network."]},
 {h:"Data and state",p:["A container's own files disappear when it is removed. Databases and uploads need volumes, storage that lives outside the container, or a managed database service."]},
 {h:"Key terms",gloss:[["Dockerfile","Instructions to build an image"],["Image","A packaged, read-only template"],["Container","A running instance of an image"],["Registry","A place to store and share images"],["Volume","Persistent storage for containers"]]}
],
quiz:[["What is the difference between an image and a container?","An image is the template; a container is a running instance."],["What builds an image?","A Dockerfile."],["Why use volumes?","To keep data when containers are replaced."],["What does Docker Compose do?","Runs several containers together from one file."]],
deeper:["dockerOverview"]},
{prac:["Ask for image tags in release notes; 'latest' isn't a version you can roll back to.","When onboarding takes days, a Compose setup can cut it to an hour."],
 mis:[["Containers are lightweight VMs.","They share the host kernel; isolation is lighter."],["Containers store data safely.","Use volumes or external databases for persistence."],["Docker and Kubernetes compete.","Docker builds and runs containers; Kubernetes orchestrates many of them."]]});

addTopic({id:"dev10",cat:DEV,t:"Kubernetes at a high level",d:"Understand",p:"P0",n:"New",h:2,
what:"Kubernetes is an open-source platform that runs and manages containers across a cluster of machines. You declare what you want (for example, three copies of the backend), and Kubernetes keeps reality matching: placing containers, restarting failed ones, scaling and routing traffic.",
why:"Many companies run production on Kubernetes. Knowing the vocabulary helps you follow capacity, deployment and incident discussions.",
concepts:["Cluster, node, control plane","Pod, deployment, service","Desired state and self-healing","Scaling and rolling updates","Ingress for external traffic","Managed Kubernetes: EKS, AKS, GKE"],
learn:["k8sOverview"],
doIt:"Draw a simple cluster: two nodes, a backend deployment with three pods, a service in front, and an ingress for internet traffic.",
prove:"Explain what Kubernetes does automatically when one node crashes.",
interview:"Do we need Kubernetes for our product? How would you decide?",
covers:["Orchestration (Kubernetes)","Kubernetes, Pods, Services"]},
{sections:[
 {h:"Core objects",table:[["Object","Plain meaning"],["Cluster","A group of machines managed together"],["Node","One machine in the cluster"],["Pod","The smallest unit: one or more containers running together"],["Deployment","Keeps a set number of identical pods running and handles updates"],["Service","A stable address that load-balances across pods"],["Ingress","Routes outside traffic into services"]]},
 {h:"Desired state",p:["You write YAML describing what should run. Kubernetes constantly compares that with reality and fixes differences: if a pod dies, it starts a new one. The Kubernetes docs list service discovery and load balancing, self-healing and automated rollouts among its features."]},
 {h:"When it's worth it",table:[["Situation","Kubernetes?"],["Many services, multiple teams, need for portability","Often yes"],["A single app or small team","Usually simpler options: a managed app platform or serverless"],["Heavy compliance or on-premises needs","Often yes, with expertise"]],p:["Kubernetes adds operational complexity. Managed versions from AWS (EKS), Azure (AKS) and Google (GKE) reduce, but don't remove, that burden."]},
 {h:"Key terms",gloss:[["Pod","The smallest deployable unit in Kubernetes"],["Deployment","Manages replicated pods and updates"],["Service","A stable network endpoint for pods"],["Node","A machine in the cluster"],["Orchestration","Automated management of many containers"]]}
],
quiz:[["What is a pod?","The smallest deployable unit, one or more containers."],["What happens when a pod crashes?","Kubernetes starts a replacement to match the desired state."],["What gives pods a stable address?","A service."],["Is Kubernetes right for every product?","No; small apps often do better with simpler platforms."]],
deeper:["k8sOverview","dockerOverview"]},
{prac:["When Kubernetes is proposed, ask who will run it and what it replaces; operational cost is the hidden line item.","Learn to read a deployment's replica count and image tag; they answer many incident questions."],
 mis:[["Kubernetes makes apps scalable automatically.","Apps must be designed to run as many copies."],["Kubernetes is a container runtime.","It orchestrates containers run by a runtime."],["Managed Kubernetes needs no expertise.","Teams still own configuration, upgrades and security."]]});

addTopic({id:"dev11",cat:DEV,t:"Infrastructure as code and configuration management",d:"Understand",p:"P1",n:"New",h:1.5,
what:"Infrastructure as code (IaC) means defining servers, networks, databases and permissions in files that are versioned and reviewed, then applied by a tool such as Terraform. Configuration management tools such as Ansible keep the software and settings on servers consistent.",
why:"IaC makes environments repeatable, reviewable and recoverable. It turns 'someone clicked something in the console' into a change you can see in a pull request.",
concepts:["Declarative configuration","Plan and apply","State files","Modules and reuse","Drift between code and reality","Configuration management tools"],
learn:["tfIntro"],
doIt:"Read the Terraform intro and write, in plain English, the plan you'd expect for creating one storage bucket and one database.",
prove:"Write a short policy: which infrastructure changes must go through IaC, and who reviews them.",
interview:"Why would a team move from console changes to infrastructure as code?",
covers:["Infrastructure as Code (Terraform)","Configuration Management"]},
{sections:[
 {h:"How Terraform works",steps:["Write: describe the desired resources in configuration files.","Plan: Terraform shows what it will create, change or destroy.","Review: the plan is checked, often in a pull request.","Apply: Terraform makes the changes and records them in a state file."],p:["HashiCorp describes Terraform as declarative: files describe the end state, and Terraform works out the steps. It keeps a state file as the source of truth about real infrastructure."]},
 {h:"Why it helps",bullets:["Repeatable: create identical dev, staging and production.","Reviewable: changes go through pull requests.","Recoverable: rebuild an environment from code after a disaster.","Auditable: history shows who changed what and when."]},
 {h:"Provisioning vs configuration",table:[["Type","Does","Examples"],["Provisioning","Creates infrastructure","Terraform, AWS CloudFormation, Pulumi"],["Configuration management","Sets up software and settings on servers","Ansible, Chef, Puppet"]]},
 {h:"Drift",p:["Drift happens when someone changes infrastructure manually so it no longer matches the code. The next apply may undo the manual fix, or fail. Teams detect drift regularly and restrict console access for changes."]},
 {h:"Key terms",gloss:[["IaC","Managing infrastructure through versioned code"],["Declarative","Describing the end state, not the steps"],["Plan","A preview of changes before applying"],["State file","Record of what infrastructure exists"],["Drift","Difference between code and real infrastructure"]]}
],
quiz:[["What does 'terraform plan' show?","What will be created, changed or destroyed."],["What is drift?","Real infrastructure no longer matching the code."],["Name a configuration management tool.","Ansible, Chef or Puppet."],["Why is IaC good for disaster recovery?","Environments can be rebuilt from code."]],
deeper:["tfIntro"]},
{prac:["Ask for the Terraform plan output in change reviews for production infrastructure; it shows impact in plain terms.","Treat manual console changes in production as incidents to learn from."],
 mis:[["IaC is only for big companies.","Even small teams benefit from repeatable environments."],["Writing IaC once is enough.","Code and reality drift; check regularly."],["Terraform configures apps.","It provisions infrastructure; app config is separate."]]});

addTopic({id:"dev12",cat:DEV,t:"Cloud platforms: AWS, Azure, GCP core services",d:"Understand",p:"P0",n:"New",h:3,
what:"Cloud platforms rent computing resources on demand. AWS, Microsoft Azure and Google Cloud offer similar building blocks: virtual machines, storage, databases, serverless functions and networking, priced by usage.",
why:"Cloud choices drive cost, speed and risk. TPMs often run migrations, cost reviews and vendor discussions, so the core services and pricing models need to be familiar.",
concepts:["IaaS, PaaS, SaaS","Regions and availability zones","Compute: EC2, Azure VMs, Compute Engine","Storage: S3, Blob Storage, Cloud Storage","Databases: RDS and equivalents","Serverless: Lambda, Azure Functions, Cloud Run functions","Pay-as-you-go and reserved pricing"],
learn:["awsOverview","rmBe"],
doIt:"Map your product's components to cloud services: where the app runs, where files are stored, which database, and what serverless functions exist.",
prove:"Write a one-page cloud cost summary for a product: top five services by cost and one saving idea for each.",
interview:"Explain cloud computing to a business stakeholder in two minutes.",
covers:["Cloud Infrastructure (AWS/GCP)","AWS, Azure, GCP","EC2, S3, RDS, Lambda","Cloud Hosting & Infrastructure","AWS Skill Builder"]},
{sections:[
 {h:"Service models",table:[["Model","You manage","Example"],["IaaS","OS, runtime, app","Virtual machines (EC2)"],["PaaS","App and data","Managed app platforms, managed databases"],["SaaS","Just usage","Gmail, Jira"]],p:["The AWS overview whitepaper describes cloud computing as on-demand delivery of IT resources over the internet with pay-as-you-go pricing."]},
 {h:"Equivalent core services",table:[["Need","AWS","Azure","Google Cloud"],["Virtual machines","EC2","Virtual Machines","Compute Engine"],["Object storage","S3","Blob Storage","Cloud Storage"],["Relational database","RDS","Azure SQL Database","Cloud SQL"],["Serverless functions","Lambda","Functions","Cloud Run functions"],["Kubernetes","EKS","AKS","GKE"]]},
 {h:"Regions and zones",p:["A region is a geographic area, such as Mumbai. Each region has several availability zones, separate data centres with independent power and networking. Running across zones protects against one data centre failing; choosing the region affects latency and data residency."]},
 {h:"Cost basics",bullets:["On-demand: pay by the hour or second, flexible but priciest.","Reserved or savings plans: commit for one to three years for discounts.","Spot or preemptible: cheap spare capacity that can be taken back.","Data transfer out of the cloud often costs more than expected.","Tag resources by team and product so costs can be allocated."]},
 {h:"Key terms",gloss:[["Region","A geographic cloud location"],["Availability zone","An isolated data centre within a region"],["IaaS","Infrastructure as a service"],["Serverless","Running code without managing servers"],["Egress","Data leaving the cloud, often charged"]]}
],
quiz:[["What is the AWS equivalent of Azure Blob Storage?","S3."],["Why use multiple availability zones?","To survive the failure of one data centre."],["Name three pricing options.","On-demand, reserved or savings plans, spot (any three)."],["What is egress?","Data leaving the cloud, often charged."]],
deeper:["awsOverview","awsVpc"]},
{prac:["Insist on cost allocation tags from day one; untagged spend is impossible to manage later.","Ask for the region choice to be documented with the data residency reason."],
 mis:[["Cloud is always cheaper.","Without management, it can cost more than on-premises."],["One provider is clearly best.","They're broadly equivalent; fit, skills and contracts decide."],["Serverless has no servers.","Servers exist; the provider manages them."]]});

addTopic({id:"dev13",cat:DEV,t:"Cloud networking and security: VPC, security groups, IAM",d:"Understand",p:"P0",n:"New",h:2,
what:"A VPC (virtual private cloud) is your private network inside the cloud, split into subnets. Security groups act as firewalls around resources. IAM (identity and access management) controls who and what can do which actions on which resources. Load balancers spread traffic across servers.",
why:"Most cloud security incidents come from misconfigured networks and permissions. Understanding these pieces helps you review designs and ask about exposure.",
concepts:["VPC and subnets (public and private)","Security groups and network ACLs","Load balancers","IAM users, roles and policies","Least privilege","Root account protection"],
learn:["awsVpc","awsIam","cfLb"],
doIt:"Draw a simple VPC: a public subnet with a load balancer, a private subnet with app servers, and a private subnet with the database. Mark which ports are open between them.",
prove:"Write five questions you'd ask in a design review about network exposure and permissions.",
interview:"How would you make sure our database isn't exposed to the internet?",
covers:["Virtual Network, VPC","Subnet, Security Group","IAM, Load Balancer"]},
{sections:[
 {h:"A typical layout",flow:[["Internet",[["Users","HTTPS 443"]]],["Public subnet",[["Load balancer","only public entry"]]],["Private subnets",[["App servers","port from LB only"],["Database","port from app only"]]]],flowLabel:"Three-tier VPC layout"},
 {h:"Networking pieces",table:[["Piece","Role"],["VPC","Your isolated network in the cloud"],["Public subnet","Reachable from the internet, for load balancers"],["Private subnet","Not directly reachable, for apps and databases"],["Security group","Allow-list of traffic to a resource"],["Load balancer","Spreads traffic and checks server health"],["NAT gateway","Lets private servers reach out without being reachable"]]},
 {h:"IAM",p:["AWS's IAM guide explains that an account starts with a root user with full access and strongly recommends not using it for everyday tasks. Instead, people and applications get identities with policies granting only the actions they need."],bullets:["Users: people or long-lived identities (prefer federated sign-in).","Roles: temporary permissions assumed by services or people.","Policies: JSON rules allowing or denying actions on resources.","Least privilege: start with nothing and add what's needed."]},
 {h:"Review questions",bullets:["Is the database in a private subnet with no public IP?","Which security group rules allow traffic from 0.0.0.0/0 (anywhere)?","Is multi-factor authentication on for the root and admin accounts?","Do apps use roles instead of stored access keys?"]},
 {h:"Key terms",gloss:[["VPC","A private network in the cloud"],["Subnet","A section of a VPC"],["Security group","A virtual firewall for resources"],["IAM role","A set of temporary permissions"],["Least privilege","Minimum access necessary"]]}
],
quiz:[["Where should a database usually sit?","In a private subnet."],["What is a security group?","A virtual firewall listing allowed traffic."],["Why avoid the root account for daily work?","It has full access; misuse or theft is catastrophic."],["What does 0.0.0.0/0 in a rule mean?","Traffic from anywhere on the internet."]],
deeper:["awsVpc","awsIam","cfLb"]},
{prac:["Ask for a network diagram in every architecture review; exposure problems are visible at a glance.","Track 'resources open to 0.0.0.0/0' as a security metric."],
 mis:[["Cloud resources are private by default everywhere.","Misconfiguration can expose them publicly."],["IAM is only for people.","Applications and services need identities too."],["A firewall at the edge is enough.","Defence in depth means rules around each tier."]]});

addTopic({id:"dev14",cat:DEV,t:"Auto scaling, storage types and managed services",d:"Understand",p:"P1",n:"New",h:1.5,
what:"Auto scaling adds or removes servers automatically based on demand. Cloud storage comes in three types: block (disks for servers), file (shared folders) and object (files with metadata in buckets, such as S3). Managed services let the provider run components such as databases, queues and caches for you.",
why:"These choices affect cost, performance and team workload. TPMs weigh build-vs-buy and scale plans every quarter.",
concepts:["Scaling policies and metrics","Minimum, desired and maximum capacity","Block, file and object storage","Storage classes and lifecycle rules","Managed vs self-managed services","Shared responsibility"],
learn:["awsStorage","awsOverview"],
doIt:"For one product, list which storage type each kind of data uses (database disks, user uploads, logs, backups) and whether each service is managed.",
prove:"Write a recommendation on moving one self-managed component to a managed service, with costs and risks.",
interview:"Our traffic spikes every evening. How should our infrastructure handle that?",
covers:["Auto Scaling","Object Storage, Block Storage","Managed Services"]},
{sections:[
 {h:"Auto scaling",bullets:["Set a minimum (always running), desired, and maximum (cost cap) number of instances.","Scale on a metric such as CPU, requests per server or queue length.","Scheduled scaling handles predictable peaks like evenings or sales.","Apps must be stateless so any instance can serve any request."]},
 {h:"Storage types",table:[["Type","Like","AWS example","Good for"],["Block","A hard disk attached to one server","EBS","Databases, OS disks"],["File","A shared network drive","EFS","Shared folders across servers"],["Object","A huge web-accessible bucket","S3","Uploads, media, backups, data lakes"]],p:["AWS's comparison explains that the three types differ in how data is organised and accessed; object storage scales almost without limit and suits unstructured data."]},
 {h:"Managed services",table:[["Self-managed","Managed"],["Install and patch PostgreSQL on a VM","Use a managed database (RDS, Cloud SQL)"],["Run your own Redis cluster","Use a managed cache"],["Operate Kafka","Use a managed streaming service"]],p:["Managed services cost more per unit but save engineering time on patching, backups and failover. Under the shared responsibility model the provider secures the platform; you still own data, access and configuration."]},
 {h:"Key terms",gloss:[["Auto scaling","Automatically adjusting capacity to demand"],["Stateless","An app that keeps no user state on the server itself"],["Object storage","Storage of files as objects in buckets"],["Managed service","A component operated by the provider"],["Shared responsibility","Split of security duties between provider and customer"]]}
],
quiz:[["Which storage type suits user uploads?","Object storage."],["Why must apps be stateless to scale out?","So any instance can handle any request."],["What does a maximum instance count protect?","Cost."],["What do you still own with a managed database?","Data, access control and configuration."]],
deeper:["awsStorage","awsOverview"]},
{prac:["Ask for scaling limits and the cost at maximum scale; finance should never be surprised by a traffic spike.","Review storage lifecycle rules; old logs and backups often cost more than expected."],
 mis:[["Auto scaling fixes all performance problems.","Databases and slow code still bottleneck."],["Managed means no responsibility.","You still own data and access."],["Object storage is a disk.","It's accessed over APIs, not mounted like a drive."]]});

addTopic({id:"dev15",cat:DEV,t:"Deployment strategies: blue-green, canary, rolling, zero downtime",d:"Understand",p:"P0",n:"New",h:2,
what:"Deployment strategies control how a new version replaces the old one. Rolling replaces servers a few at a time. Blue-green runs two identical environments and switches traffic at once. Canary sends a small share of users to the new version first. All aim for zero downtime and easy rollback.",
why:"Choosing the strategy sets release risk, cost and rollback speed. TPMs plan releases and communicate risk, so this vocabulary is essential.",
concepts:["Rolling deployment","Blue-green deployment","Canary release","Feature flags vs deployment strategies","Database changes and backward compatibility","Rollback plans"],
learn:["fowlerBG","fowlerCanary"],
doIt:"For a feature in your product, choose a deployment strategy and write why, including how you'd roll back.",
prove:"Write a release plan for a risky change using a canary: stages, percentages, metrics watched and go/no-go criteria.",
interview:"How would you release a risky change to a payment flow with minimal impact?",
covers:["Blue-Green Deployment","Canary Deployment","Rolling Deployment","Zero-Downtime Deployment"]},
{sections:[
 {h:"Comparing strategies",table:[["Strategy","How","Rollback","Cost"],["Rolling","Replace instances in batches","Roll forward or redeploy old version","Low"],["Blue-green","Prepare new environment, switch all traffic","Switch back instantly","Double capacity during switch"],["Canary","Send 1%, then 10%, then 50%, then 100%","Route traffic back","Moderate, needs good monitoring"]],p:["Martin Fowler describes blue-green as two production environments, one live, so the cut-over and rollback are quick. His canary release article describes rolling out to a small subset of users first before everyone."]},
 {h:"A canary plan",steps:["Deploy the new version alongside the old.","Route 1% of traffic; watch errors, latency and business metrics for 30 minutes.","Increase to 10%, then 50%, checking the same signals.","Go to 100% when metrics stay within thresholds.","Roll back immediately if any threshold is breached."]},
 {h:"The database catch",p:["Zero-downtime releases break if a database change isn't compatible with both versions running at once. The common pattern is expand and contract: add new columns first, deploy code that uses them, then remove old columns in a later release."]},
 {h:"Feature flags",p:["Flags separate deploying code from releasing features. You can deploy everything, then turn a feature on for staff, then 5% of users, without redeploying. They need cleanup, or old flags pile up as technical debt."]},
 {h:"Key terms",gloss:[["Rolling deployment","Gradually replacing instances"],["Blue-green","Switching between two identical environments"],["Canary","Releasing to a small group first"],["Rollback","Returning to the previous version"],["Expand and contract","Making database changes in compatible steps"]]}
],
quiz:[["Which strategy gives the fastest rollback?","Blue-green, by switching traffic back."],["What does a canary release need most?","Good monitoring to compare versions."],["Why can database changes break zero-downtime releases?","Old and new code run at the same time against one database."],["How do feature flags differ from deployment strategies?","Flags control who sees a feature without redeploying."]],
deeper:["fowlerBG","fowlerCanary","vercelDeploys"]},
{prac:["Write go/no-go thresholds before the release, not during it; decisions under pressure are worse.","Add 'database compatible with old version?' to the release checklist."],
 mis:[["Zero downtime is automatic in the cloud.","It needs the right strategy and compatible changes."],["Canary means beta testers.","It's a share of real production traffic."],["Rollback is always possible.","Irreversible data changes can block it; plan ahead."]]});

addTopic({id:"dev16",cat:DEV,t:"Environment variables and secrets management",d:"Understand",p:"P0",n:"New",h:1,
what:"Configuration that differs between environments (database addresses, feature switches, API keys) should live outside the code, usually in environment variables. Secrets, such as passwords and keys, need extra protection in a secrets manager with access control, auditing and rotation.",
why:"Leaked secrets are one of the most common causes of breaches. Clean config handling also makes the same build run in every environment.",
concepts:["Config vs code","Environment variables and .env files","Secrets managers","Access control and audit","Rotation","Secret scanning"],
learn:["twelveConfig","ghSecret"],
doIt:"Look at this project's .env.example and docker-compose.yml. List which values are config and which are secrets.",
prove:"Write a secrets policy for a team: where secrets live, who can read them, how often they rotate and what to do after a leak.",
interview:"A developer committed an API key to GitHub. What do you do?",
covers:["Environment Variables","Secrets Management"]},
{sections:[
 {h:"Config outside the code",p:["The Twelve-Factor App says config, meaning anything that varies between deploys, should be stored in environment variables and kept strictly separate from code. That's why this project ships a .env.example with placeholders and keeps the real .env out of Git."]},
 {h:"Config vs secrets",table:[["Value","Type","Where"],["Log level","Config","Environment variable"],["Database URL without password","Config","Environment variable"],["Database password","Secret","Secrets manager, injected at runtime"],["Third-party API key","Secret","Secrets manager"],["JWT signing key","Secret","Secrets manager"]]},
 {h:"Secrets managers",bullets:["Examples: AWS Secrets Manager, Azure Key Vault, Google Secret Manager, HashiCorp Vault, GitHub Actions secrets.","Encrypted storage, fine-grained access, audit logs.","Support rotation without code changes."]},
 {h:"After a leak",steps:["Revoke or rotate the key immediately; deleting the commit is not enough.","Check logs for misuse.","Remove it from the code and history if needed.","Find why it happened and add secret scanning to prevent repeats."],p:["GitHub's secret scanning detects many known credential formats in repositories and can alert or block pushes."]},
 {h:"Key terms",gloss:[["Environment variable","A setting provided by the running environment"],[".env file","A local file of environment variables, not committed"],["Secrets manager","A secure store for credentials"],["Rotation","Replacing secrets regularly"],["Secret scanning","Automated detection of committed credentials"]]}
],
quiz:[["Where should config that varies by environment live?","In environment variables, outside the code."],["What's the first step after a key leak?","Revoke or rotate the key."],["Why commit a .env.example but not .env?","The example documents settings; the real file holds secrets."],["Name two secrets managers.","AWS Secrets Manager, Azure Key Vault, Google Secret Manager, Vault, GitHub secrets (any two)."]],
deeper:["twelveConfig","ghSecret"]},
{prac:["Run a 'leaked key' drill once; teams that have practised rotate in minutes, not days.","Ask for secret scanning on every repository as a default."],
 mis:[["Deleting the commit removes the leak.","It remains in history and copies; rotate the key."],["Private repos don't need secret hygiene.","Access widens over time; treat all repos as exposable."],["Environment variables are fully secure.","They can leak through logs and debugging; use managers for secrets."]]});

addTopic({id:"dev17",cat:DEV,t:"Web servers, hosting, domains and SSL renewal",d:"Understand",p:"P1",n:"New",h:1.5,
what:"Web servers such as Nginx and Apache receive HTTP requests and serve files or pass requests to applications (as a reverse proxy). Hosting is where the app runs. Domains are mapped to servers through DNS. SSL/TLS certificates enable HTTPS and must be renewed before they expire.",
why:"Expired certificates and wrong DNS records cause embarrassing outages. Launches and migrations need someone to own these details.",
concepts:["Web server vs app server","Reverse proxy","Hosting options","DNS records: A, CNAME","TLS certificates and expiry","Automated renewal with Let's Encrypt"],
learn:["nginxGuide","leHow","cfDns","cfTls"],
doIt:"Check the certificate of a website you use (padlock icon): who issued it and when it expires.",
prove:"Write a launch checklist for a new domain: DNS records, certificate, redirects from HTTP to HTTPS, monitoring for expiry.",
interview:"Our site went down because the certificate expired. How do we stop that happening again?",
covers:["Nginx, Apache","Hosting, Domain Mapping","SSL Renewal, DNS Configuration"]},
{sections:[
 {h:"Web servers and reverse proxies",p:["Nginx's beginner's guide covers serving static content and setting up a simple proxy server. In most stacks, Nginx sits in front of the application, handling HTTPS, compression and routing, and forwards requests to the app."]},
 {h:"DNS mapping",table:[["Record","Purpose","Example"],["A","Points a name to an IPv4 address","app.example.com to 203.0.113.10"],["CNAME","Points a name to another name","www to example.netlify.app"],["MX","Mail servers","Email routing"],["TXT","Verification and policies","Domain ownership, SPF"]],p:["DNS changes can take time to spread because of caching (TTL). Lower the TTL before a migration."]},
 {h:"Certificates and renewal",p:["Let's Encrypt issues free certificates through the ACME protocol: a client on your server proves you control the domain and gets a certificate. Renewing means repeating that process. Its certificates are short-lived, so renewal must be automated and monitored."],bullets:["Automate renewal with a client such as Certbot or your platform's built-in support.","Monitor expiry dates and alert well in advance.","Keep an inventory of all domains and certificates, including old marketing sites."]},
 {h:"Hosting options",table:[["Option","Fits"],["Static hosting or CDN","Marketing sites, documentation"],["Platform as a service","Most web apps"],["VMs or containers","Custom needs, more control"],["Serverless","Spiky or event-driven workloads"]]},
 {h:"Key terms",gloss:[["Web server","Software that handles HTTP requests"],["Reverse proxy","A server that forwards requests to backend apps"],["DNS record","An entry mapping names to destinations"],["TLS certificate","Proof of identity enabling HTTPS"],["TTL","How long DNS answers are cached"]]}
],
quiz:[["What does a reverse proxy do?","Receives requests and forwards them to backend apps."],["Which DNS record points a name to another name?","CNAME."],["How do you avoid certificate expiry outages?","Automate renewal and monitor expiry dates."],["Why lower TTL before a migration?","So DNS changes take effect faster."]],
deeper:["nginxGuide","leHow","cfDns","cfTls"]},
{prac:["Keep a domain and certificate register with owners and expiry dates; forgotten domains cause outages.","Add expiry monitoring to the same alerting used for uptime."],
 mis:[["Certificates renew themselves.","Only if automation is set up and working."],["DNS changes are instant.","Caches can hold old answers for the TTL period."],["Nginx is the app.","It usually fronts the app."]]});

addTopic({id:"dev18",cat:DEV,t:"Observability: logs, metrics, traces and alerting",d:"Understand",p:"P0",n:"New",h:2,
what:"Observability is how well you can understand what a system is doing from its outputs. The three main signals are logs (event records), metrics (numbers over time) and traces (a request's path across services). Alerting notifies people when signals cross thresholds that matter to users.",
why:"You can't manage reliability you can't see. TPMs use dashboards for status, incident calls and planning.",
concepts:["Logs, metrics, traces","Prometheus and Grafana","The four golden signals: latency, traffic, errors, saturation","Dashboards for different audiences","Alerting on symptoms, not causes","Alert fatigue"],
learn:["promDocs","otelGenai"],
doIt:"Sketch a dashboard for one service with the four golden signals and one business metric.",
prove:"Write alert rules for that service: condition, severity, who is paged and the first action.",
interview:"How would you know our service is unhealthy before customers tell us?",
covers:["Monitoring & Observability (Prometheus, Grafana)","Logs, Metrics, Traces","Alerting"]},
{sections:[
 {h:"Three signals",table:[["Signal","Answers","Example"],["Logs","What happened?","Payment failed for order 123: card declined"],["Metrics","How much and how often?","Error rate 2.1%, p95 latency 800 ms"],["Traces","Where did time go?","Checkout request: 40 ms API, 700 ms payment provider"]]},
 {h:"Tools",p:["Prometheus, an open-source monitoring and alerting toolkit originally built at SoundCloud, collects metrics as time series. Grafana visualises them in dashboards. OpenTelemetry is the common standard for collecting traces, metrics and logs across vendors."]},
 {h:"The four golden signals",table:[["Signal","Measures"],["Latency","How long requests take"],["Traffic","How much demand there is"],["Errors","How many requests fail"],["Saturation","How full resources are: CPU, memory, connections"]],p:["These come from Google's SRE practice and are a good default for any service dashboard."]},
 {h:"Good alerting",bullets:["Alert on user-visible symptoms (errors, slowness), not every internal cause.","Each alert needs an owner and a runbook link.","Too many alerts cause fatigue; people start ignoring them.","Review alerts after incidents: did the right one fire, early enough?"]},
 {h:"Key terms",gloss:[["Observability","Ability to understand a system from its outputs"],["Metric","A numeric measurement over time"],["Trace","A record of a request's path"],["Golden signals","Latency, traffic, errors, saturation"],["Alert fatigue","Ignoring alerts because there are too many"]]}
],
quiz:[["Name the three main observability signals.","Logs, metrics, traces."],["List the four golden signals.","Latency, traffic, errors, saturation."],["Why alert on symptoms?","They reflect user impact and cut noise."],["What does Grafana do?","Visualises metrics in dashboards."]],
deeper:["promDocs","otelGenai"]},
{prac:["Have one dashboard for executives (availability, key business metric) and another for engineers; one size fits nobody.","Count alerts per on-call shift; more than a handful usually means noise."],
 mis:[["More dashboards mean better observability.","Focused dashboards answer questions faster."],["Logs are enough.","Metrics show trends; traces show where time goes."],["Alert on everything.","Noise hides the alerts that matter."]]});

addTopic({id:"dev19",cat:DEV,t:"SLA, SLO, SLI and error budgets",d:"Understand",p:"P0",n:"Refresh",h:1.5,
what:"An SLI (service level indicator) is a measurement of service, such as the share of successful requests. An SLO (service level objective) is the target for it, such as 99.9% per month. An SLA (service level agreement) is a contract with customers, usually with penalties. The error budget is the allowed unreliability: 100% minus the SLO.",
why:"SLOs turn reliability into a shared, numeric agreement between product and engineering. Error budgets help decide when to ship features and when to fix reliability.",
concepts:["SLI, SLO, SLA","Choosing user-centred indicators","Nines and allowed downtime","Error budgets","Error budget policies","SLOs stricter than SLAs"],
learn:["sreSlo"],
doIt:"Define two SLIs and SLOs for a product you know, and calculate the monthly error budget for each.",
prove:"Write an error budget policy: what happens when 50%, 75% and 100% of the budget is used.",
interview:"Engineering wants to pause features to fix reliability; product wants to ship. How do you decide?",
covers:["Uptime, SLA, SLO, SLI"]},
{sections:[
 {h:"The three terms",table:[["Term","What","Example"],["SLI","A measured indicator","Share of checkout requests that succeed in under 2 seconds"],["SLO","Internal target","99.9% over 30 days"],["SLA","Customer contract","99.5% monthly, with service credits if missed"]],p:["Google's SRE book defines an SLO as a target value or range for a service level measured by an SLI."]},
 {h:"What the nines mean",table:[["Availability","Downtime per 30 days"],["99%","About 7 hours 12 minutes"],["99.9%","About 43 minutes"],["99.95%","About 22 minutes"],["99.99%","About 4 minutes"]],p:["Each extra nine costs much more to achieve. Pick the level users actually need."]},
 {h:"Error budgets",p:["If the SLO is 99.9%, the error budget is 0.1%: in a month of 1 million requests, 1,000 can fail. While budget remains, the team can take risks and ship. When it's spent, priority shifts to reliability until it recovers."]},
 {h:"Keep the SLA looser",p:["Set the internal SLO tighter than the external SLA, so you get a warning and act before contractual penalties apply."]},
 {h:"Key terms",gloss:[["SLI","A measurement of service level"],["SLO","A target for an SLI"],["SLA","A contractual commitment to customers"],["Error budget","Allowed failure within the SLO"],["Nines","Shorthand for availability percentages"]]}
],
quiz:[["What is the error budget for a 99.9% SLO?","0.1% of requests or time."],["About how much downtime does 99.9% allow per 30 days?","About 43 minutes."],["Why keep the SLO stricter than the SLA?","To act before contractual penalties."],["What happens when the error budget is spent?","Priority shifts to reliability work."]],
deeper:["sreSlo","atlMetrics"]},
{prac:["Put SLO status in the sprint review; it makes the reliability-vs-features trade-off explicit and data-driven.","Agree the error budget policy before you need it."],
 mis:[["100% availability is the goal.","It's impossibly expensive; users don't need it."],["SLA and SLO are the same.","The SLA is a contract; the SLO is an internal target."],["Uptime is the only SLI.","Latency and correctness matter too."]]});

addTopic({id:"dev20",cat:DEV,t:"Incident management, RCA, MTTR and MTBF",d:"Understand",p:"P0",n:"Refresh",h:2,
what:"Incident management is the process for detecting, responding to and learning from service disruptions. Roles such as incident commander and communications lead keep response organised. After the incident, a root cause analysis (RCA) or blameless postmortem finds contributing causes and actions. MTTR and MTBF measure recovery speed and failure frequency.",
why:"TPMs often coordinate incident communication and own the follow-up actions. A calm, structured process shortens outages and builds trust.",
concepts:["Severity levels","Incident roles","Status communication","Blameless postmortems","Five whys and contributing factors","MTTR, MTBF, MTTA","Shadowing a production deployment"],
learn:["srePostmortem","atlMetrics"],
doIt:"Read one public postmortem from a well-known company and identify the timeline, impact, contributing causes and action items.",
prove:"Write an incident process for your team: severity definitions, roles, update cadence and postmortem template.",
interview:"Tell me about a production incident you managed. What did you do and what changed afterwards?",
covers:["Incident Management","RCA","MTTR, MTBF","Production Deployment (Level 4: shadow a deployment)"]},
{sections:[
 {h:"During an incident",table:[["Role","Does"],["Incident commander","Coordinates, decides, keeps focus"],["Technical lead","Investigates and fixes"],["Communications lead","Updates stakeholders and customers on a fixed cadence"],["Scribe","Records the timeline"]],steps:["Declare the incident and set severity.","Assign roles.","Mitigate first: restore service, then find root cause.","Update stakeholders every 30 minutes, even if nothing changed.","Declare resolved and schedule the postmortem."]},
 {h:"Blameless postmortems",p:["Google's SRE book describes blameless postmortems as focusing on contributing causes without blaming individuals or teams, because people hide information if they fear punishment. Good postmortems include a timeline, impact, causes, what went well and owned action items with dates."]},
 {h:"The metrics",table:[["Metric","Meaning","Formula"],["MTTA","Mean time to acknowledge","Time from alert to someone responding"],["MTTR","Mean time to recover (or repair)","Total downtime ÷ number of incidents"],["MTBF","Mean time between failures","Total uptime ÷ number of failures"]],p:["Atlassian notes availability can be estimated as MTBF ÷ (MTBF + MTTR), and advises teams to define which MTTR they mean, since the R can stand for repair, recovery, respond or resolve."]},
 {h:"Shadowing a deployment",bullets:["Join a production release as an observer.","Note each step, check and approval.","Ask what would trigger a rollback and who decides.","Write down what was manual and could be automated."]},
 {h:"Key terms",gloss:[["Incident commander","The person coordinating the response"],["Postmortem","A written review after an incident"],["Blameless","Focusing on systems, not individuals"],["MTTR","Average time to restore service"],["MTBF","Average time between failures"]]}
],
quiz:[["What comes first during an incident: root cause or mitigation?","Mitigation."],["What does a communications lead do?","Gives stakeholders regular updates."],["Why are postmortems blameless?","So people share information openly."],["How is availability estimated from MTBF and MTTR?","MTBF ÷ (MTBF + MTTR)."]],
deeper:["srePostmortem","atlMetrics","sreSlo"]},
{prac:["Track postmortem action items like any other backlog; unfinished actions are why incidents repeat.","Volunteer as communications lead; it's where TPMs add the most value in incidents."],
 mis:[["RCA finds the single root cause.","Incidents usually have several contributing factors."],["Blameless means no accountability.","Teams are accountable for fixing systems and completing actions."],["MTTR alone shows reliability.","Pair it with incident frequency and impact."]]});

addTopic({id:"dev21",cat:DEV,t:"Disaster recovery and backups",d:"Understand",p:"P0",n:"New",h:1.5,
what:"Disaster recovery (DR) is the plan for restoring service after a major event such as a region outage, data corruption or ransomware. It is defined by RTO (how quickly service must be back) and RPO (how much data loss, measured in time, is acceptable). Backups are one part; tested restores are what matter.",
why:"Leaders ask 'what if the data centre goes down?' The TPM needs clear RTO and RPO commitments, costs and tested evidence.",
concepts:["RTO and RPO","DR strategies: backup and restore, pilot light, warm standby, active-active","Backups vs replication","Testing restores","Runbooks and DR drills","Ransomware and immutable backups"],
learn:["awsDr"],
doIt:"For one product, agree an RTO and RPO with a business owner and map them to one of the four DR strategies.",
prove:"Write a DR test plan: scenario, steps, success criteria, who takes part and how results are recorded.",
interview:"What is the difference between RTO and RPO, and how do they affect cost?",
covers:["Disaster Recovery","Backup and Restore"]},
{sections:[
 {h:"RTO and RPO",table:[["Term","Question","Example"],["RTO","How long can we be down?","Service back within 4 hours"],["RPO","How much data can we lose?","No more than 15 minutes of transactions"]],p:["AWS's DR guidance notes lower RTO and RPO mean less downtime and data loss but cost more in resources and complexity, so targets should reflect business value."]},
 {h:"Four strategies",table:[["Strategy","Idea","Typical RTO/RPO","Cost"],["Backup and restore","Restore from backups into new infrastructure","Hours","Lowest"],["Pilot light","Core data replicated, minimal infrastructure ready","Tens of minutes","Low"],["Warm standby","Scaled-down copy always running","Minutes","Medium"],["Multi-site active-active","Full copies serving traffic in several regions","Near zero","Highest"]]},
 {h:"Backups that work",bullets:["Follow 3-2-1: three copies, two media types, one off-site.","Keep some backups immutable so ransomware can't encrypt them.","Test restores regularly; an untested backup is a hope, not a plan.","Use infrastructure as code so environments can be rebuilt quickly."]},
 {h:"DR drills",steps:["Choose a scenario, such as primary database lost.","Follow the runbook exactly.","Time each step against the RTO.","Measure data loss against the RPO.","Fix gaps in the runbook and repeat."]},
 {h:"Key terms",gloss:[["RTO","Recovery time objective: maximum acceptable downtime"],["RPO","Recovery point objective: maximum acceptable data loss"],["Pilot light","Minimal standby with data replicated"],["Warm standby","A smaller always-on copy"],["Immutable backup","A backup that can't be changed or deleted for a period"]]}
],
quiz:[["What does RPO measure?","The maximum acceptable data loss, as time."],["Which DR strategy is cheapest?","Backup and restore."],["What is the 3-2-1 rule?","Three copies, two media, one off-site."],["Why test restores?","Backups that can't be restored are worthless."]],
deeper:["awsDr"]},
{prac:["Get RTO and RPO signed off by the business owner; engineering shouldn't guess the cost of downtime.","Report the date of the last successful restore test in quarterly reviews."],
 mis:[["Replication is a backup.","Replication copies mistakes and deletions instantly."],["Cloud providers handle DR.","You design and test your own recovery."],["Backups are enough.","Recovery also needs infrastructure, runbooks and practice."]]});

addTopic({id:"dev22",cat:DEV,t:"DevSecOps and security scanning",d:"Understand",p:"P1",n:"New",h:1.5,
what:"DevSecOps builds security into every stage of delivery instead of checking at the end. Automated scans in the pipeline cover code (SAST), dependencies (SCA), secrets, containers, infrastructure code and the running app (DAST), with findings routed to the teams that own them.",
why:"Late security reviews delay releases and miss issues. Shifting checks left makes security part of normal delivery.",
concepts:["Shift left","Threat modelling","Pipeline security scans","Container and IaC scanning","Software supply chain security","Vulnerability management and SLAs"],
learn:["owaspDevsecops","codeql","zapGuide"],
doIt:"List the security checks in your product's pipeline today and mark gaps against SAST, SCA, secret scanning, container scanning and DAST.",
prove:"Write a vulnerability management policy: severity levels, fix timelines and exception process.",
interview:"How do you make security part of delivery without slowing teams down?",
covers:["DevSecOps","Security Vulnerability Scan (Level 4)"]},
{sections:[
 {h:"Security across the pipeline",flow:[["Plan",[["Threat model","design review"]]],["Code",[["SAST","code patterns"],["Secret scan","credentials"]]],["Build",[["SCA","dependencies"],["Container scan","image CVEs"],["IaC scan","misconfigs"]]],["Test and run",[["DAST","staging"],["Monitoring","runtime"]]]],flowLabel:"DevSecOps checks",p:["The OWASP DevSecOps Guideline explains how to build a secure pipeline with best practices and automation tools that shift security issues left."]},
 {h:"Running a scan finding",steps:["Scanner raises a finding with severity.","It's routed to the owning team's backlog.","Fix within the agreed timeline, such as critical in 7 days.","If it can't be fixed, record an exception with risk owner and expiry.","Re-scan to confirm."]},
 {h:"Supply chain",bullets:["Most code in an app comes from open-source packages; SCA tracks their known vulnerabilities.","Pin versions and use lockfiles.","Keep a software bill of materials (SBOM) listing components.","Verify third-party CI actions and container base images."]},
 {h:"Keeping it fast",bullets:["Run quick scans on PRs and deeper scans nightly.","Tune rules to cut false positives.","Block only on high-confidence, high-severity findings at first."]},
 {h:"Key terms",gloss:[["DevSecOps","Integrating security into DevOps practices"],["Shift left","Finding issues earlier in the lifecycle"],["SBOM","Software bill of materials listing components"],["CVE","A publicly listed vulnerability identifier"],["Exception","A recorded, time-limited acceptance of a risk"]]}
],
quiz:[["What does 'shift left' mean?","Finding security issues earlier in delivery."],["Which scan checks third-party packages?","SCA."],["What is an SBOM?","A list of the software components in a product."],["Why record exceptions with an expiry?","So accepted risks get revisited."]],
deeper:["owaspDevsecops","codeql","zapGuide"]},
{prac:["Agree fix timelines by severity with security up front, then report against them like any SLA.","Start scanners in report-only mode, tune them, then turn on blocking."],
 mis:[["DevSecOps means developers do security alone.","Security teams provide tools, guidance and review."],["More scanners mean more security.","Untriaged findings are noise."],["Security slows delivery.","Late surprises slow it more."]]});
